#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Clock-out Form Reminder: the setup wizard (#37 to #41, spec #19). The only
# supported installer. Each step gives a plain Why, What to do and an
# Example. The flow follows the prototype on prototype/setup-wizard (3a5a222).
#
#   npm run setup                      full first-time setup
#   npm run setup -- --support         the same, with the support link an integrator gave
#   npm run setup -- --step NAME       rerun one step, then apply it
#   npm run setup -- --help
#
# Everything it captures goes to the git-ignored .dev.vars, which the
# checking deploy reads (docs/RUNBOOK.md, "Where the Deployment's values
# live"). Hosted on our account, it's run on a call: we sign in to
# Cloudflare, the client does the Connecteam steps.
#
# Helpers below are inherited from EH_Webhook's wizard (~/IDP/EH_Webhook/
# scripts/setup-wizard.sh at 0c5ec92): why / todo / next_up / ok / fail, the
# quiet wrangler calls and the session log with keys redacted.

ENV_FILE="${WIZARD_ENV_FILE:-.dev.vars}"

# Every step in the order setup runs them, and the ones --step can rerun (#19, #41).
STEPS=(key timezone form timings quiet-hours recipients reminder-task sender alerts support webhook test)

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  RED=$(tput setaf 1)
else
  RED=""
fi

# why "line" ... : the step's purpose in plain language.
why() {
  printf '\n  %sWhy this step%s\n' "$BOLD" "$RESET"
  local l; for l in "$@"; do printf '    %s\n' "$l"; done
}

# todo "action" ... : numbered list of what the person will do in this step.
todo() {
  printf '\n  %sWhat to do%s\n' "$BOLD" "$RESET"
  local i=1 l line first
  for l in "$@"; do
    first=1
    # Wrap at 76 columns, continuation lines under the text, not the number.
    while IFS= read -r line; do
      if [[ -n "$first" ]]; then printf '    %s%d.%s %s\n' "$BLUE" "$i" "$RESET" "$line"; first=""
      else printf '       %s\n' "$line"; fi
    done < <(printf '%s\n' "$l" | fold -s -w 69 | sed 's/ *$//')
    i=$((i + 1))
  done
}

# example "line" ... : a worked example in real values (#18).
example() {
  printf '\n  %sExample%s\n' "$BOLD" "$RESET"
  local l; for l in "$@"; do printf '    %s%s%s\n' "$DIM" "$l" "$RESET"; done
  printf '\n'
}

ok()   { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; }

# next_up "text": how this step leads into the next one.
next_up() { printf '\n  %sNext: %s%s\n' "$DIM" "$1" "$RESET"; }

# visit URL: open it, unless WIZARD_NO_BROWSER is set (the wizard's tests).
visit() {
  if [[ -n "${WIZARD_NO_BROWSER:-}" ]]; then note "Open: $1"; else open_url "$1" || note "Open: $1"; fi
}

# save KEY VALUE "label": store a value in .dev.vars behind one plain line.
save() {
  write_env "$1" "$2" >/dev/null
  ok "Saved $3."
}

# Wrangler, quietly. WIZARD_DETAILS keeps every wrangler call's full output
# (git-ignored, cleaned and redacted like the session log); the screen shows
# one plain line per step instead.
WIZARD_DETAILS="${WIZARD_DETAILS:-$PWD/setup-wizard-$(date +%Y%m%d-%H%M%S)-wrangler.log}"

# wrangler_bin ARGS...: this repo's wrangler, or $WRANGLER_CMD (the wizard's tests).
wrangler_bin() { if [[ -n "${WRANGLER_CMD:-}" ]]; then "$WRANGLER_CMD" "$@"; else npx wrangler "$@"; fi; }

# wr: run wrangler, streaming output (for `wrangler login`).
wr() { wrangler_bin "$@"; }

# wr_quiet ARGS...: run wrangler non-interactively, its output kept out of
# sight: appended to $WIZARD_DETAILS and left in $WR_OUT.
wr_quiet() {
  local rc=0
  WR_OUT=$(wrangler_bin "$@" < /dev/null 2>&1) || rc=$?
  { printf '\n$ wrangler %s   (exit %s, %s)\n' "$*" "$rc" "$(date +%H:%M:%S)"; printf '%s\n' "$WR_OUT"; } >> "$WIZARD_DETAILS"
  chmod 600 "$WIZARD_DETAILS" 2>/dev/null || true
  return "$rc"
}

# ask_default VAR "Prompt" DEFAULT: read a value into $VAR; Enter takes
# DEFAULT (shown in brackets). Visible input, edited with Readline. Fails at
# EOF with no input.
ask_default() {
  # Underscored locals, so they can't hide the caller's variable of the same name.
  local _var="$1" _prompt="$2" _def="$3" _in _s=$'\001' _e=$'\002' _p _rc=0
  _p="  $_s$BOLD$_e$_prompt$_s$RESET$_e "
  [[ -n "$_def" ]] && _p+="$_s$DIM$_e[$_def]$_s$RESET$_e "
  read -e -r -p "$_p" _in || _rc=1
  if (( _rc )) && [[ -z "$_in" ]]; then return 1; fi
  [[ -z "$_in" ]] && _in="$_def"
  printf -v "$_var" '%s' "$_in"
}

# choose VAR "Prompt" DEFAULT LOWEST LABEL...: number the labels from 1, then
# read a choice into $VAR until it's one of them (or 0, when LOWEST is 0).
choose() {
  local var="$1" prompt="$2" def="$3" lowest="$4" i=1 l
  shift 4
  for l in "$@"; do printf '    %s%3d)%s %s\n' "$BLUE" "$i" "$RESET" "$l"; i=$((i + 1)); done
  while :; do
    ask_default "$var" "$prompt" "$def" || return 1
    if [[ "${!var}" =~ ^[0-9]+$ ]] && (( 10#${!var} >= lowest && 10#${!var} <= $# )); then
      printf -v "$var" '%d' "$((10#${!var}))"
      return 0
    fi
    fail "Type a number from the list."
  done
}

# ask_yn VAR "Question" DEFAULT: y or n into $VAR; Enter takes DEFAULT (y or n).
ask_yn() {
  local _v="$1" _q="$2" _d="$3" _a
  while :; do
    ask_default _a "$_q (y/n)" "$_d" || return 1
    case "$_a" in
      [Yy]*) printf -v "$_v" y; return 0 ;;
      [Nn]*) printf -v "$_v" n; return 0 ;;
    esac
    fail "Type y or n."
  done
}

# warn_long "text": a warning wrapped at 76 columns, continuation lines under the text.
warn_long() {
  local line first=1
  while IFS= read -r line; do
    if [[ -n "$first" ]]; then warn "$line"; first=""; else printf '    %s%s%s\n' "$YELLOW" "$line" "$RESET"; fi
  done < <(printf '%s\n' "$1" | fold -s -w 72 | sed 's/ *$//')
}

# helper ARGS...: scripts/wizard-helper.ts, its output left in $HELPER_OUT.
# Its exit status says how it went: 0 done, 1 what was typed won't do,
# 3 the key was rejected, 4 Connecteam couldn't be read.
helper() {
  local rc=0
  HELPER_OUT=$(CT_API_KEY="${CT_API_KEY:-}" npm run --silent wizard-helper -- "$@" < /dev/null 2>&1) || rc=$?
  return "$rc"
}

# example_from_helper ARGS...: the worked example the helper builds, shown as an Example.
example_from_helper() {
  local lines=() l
  helper "$@" || { note "$HELPER_OUT"; return 0; }
  while IFS= read -r l; do lines+=("$l"); done <<<"$HELPER_OUT"
  example "${lines[@]}"
}

# need_key: the saved API key, for a step rerun on its own.
need_key() {
  [[ -n "${CT_API_KEY:-}" ]] || CT_API_KEY=$(_existing CT_API_KEY || true)
  [[ -n "$CT_API_KEY" ]] || { fail "No API key saved yet. Run the key step first: npm run setup -- --step key"; exit 1; }
}

# saved_or KEY DEFAULT: the value saved in .dev.vars, or DEFAULT.
saved_or() {
  local v; v=$(_existing "$1" || true)
  printf '%s' "${v:-$2}"
}

# point "text": one bullet wrapped at 76 columns, continuation lines under the text.
point() {
  local line first=1
  while IFS= read -r line; do
    if [[ -n "$first" ]]; then step "$line"; first=""; else printf '    %s\n' "$line"; fi
  done < <(printf '%s\n' "$1" | fold -s -w 72 | sed 's/ *$//')
}

# find_by_name VAR "Prompt" DEFAULT ZERO NONE MANY LABEL...: read part of a
# name until it picks one LABEL; its index (from 0) goes into $VAR. A label
# typed in full picks it, and several matches are listed to pick from. With
# ZERO set, 0 is an answer too ($VAR is -1). NONE and MANY finish "No …
# matches" and "12 … match".
find_by_name() {
  # fb_ locals, so ask_default's and choose's can't hide them.
  local fb_var="$1" fb_prompt="$2" fb_def="$3" fb_zero="$4" fb_none="$5" fb_many="$6" fb_in fb_lower fb_i fb_n fb_m fb_shown
  shift 6
  local fb_labels=("$@")
  while :; do
    ask_default fb_in "$fb_prompt" "$fb_def" || return 1
    if [[ -n "$fb_zero" && "$fb_in" == 0 ]]; then printf -v "$fb_var" '%s' -1; return 0; fi
    if [[ -z "$fb_in" ]]; then fail "Type part of a name."; continue; fi
    fb_lower=$(printf '%s' "$fb_in" | tr '[:upper:]' '[:lower:]')
    fb_m=()
    for ((fb_i = 0; fb_i < $#; fb_i++)); do
      [[ "${fb_labels[$fb_i]}" == "$fb_in" ]] && { fb_m=("$fb_i"); break; }
      [[ "$(printf '%s' "${fb_labels[$fb_i]}" | tr '[:upper:]' '[:lower:]')" == *"$fb_lower"* ]] && fb_m+=("$fb_i")
    done
    if (( ${#fb_m[@]} == 0 )); then fail "No $fb_none matches \"$fb_in\"."; continue; fi
    if (( ${#fb_m[@]} == 1 )); then printf -v "$fb_var" '%s' "${fb_m[0]}"; return 0; fi
    if (( ${#fb_m[@]} > 20 )); then fail "${#fb_m[@]} $fb_many match. Type more of the name."; continue; fi
    fb_shown=()
    for fb_i in "${fb_m[@]}"; do fb_shown+=("${fb_labels[$fb_i]}"); done
    choose fb_n "Which one? (number)" "" 1 "${fb_shown[@]}" || return 1
    printf -v "$fb_var" '%s' "${fb_m[$((fb_n - 1))]}"
    return 0
  done
}

# json_get FIELD: read one field of the JSON on stdin.
json_get() { node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const v=JSON.parse(s)[process.argv[1]];process.stdout.write(v==null?"":String(v))}catch{}})' "$1"; }

# ── session log (#19, user story 70) ──────────────────────────────────────
# The screen clears at every stage, so keep a copy of the whole run to look
# back at or send to the integrator. `script` records the terminal while
# keeping it a real terminal, and hidden input (API keys) isn't echoed, so it
# isn't recorded. Afterwards the log is turned into plain text and every key
# and secret in .dev.vars is replaced with [redacted], in case one was pasted
# before its prompt appeared.

# clean_log FILE: strip terminal codes, then redact the values of every
# *KEY* / *SECRET* entry in $ENV_FILE.
clean_log() {
  local f="$1"
  [[ -f "$f" ]] || return 0
  perl -i -pe 's/\e\[[0-9;?]*[A-Za-z]//g; s/\e\][^\a]*\a//g; s/\e[()][A-Z0-9]//g; s/\r//g; s/[\x04\x08]//g' "$f"
  if [[ -f "$ENV_FILE" ]]; then
    local key val
    for key in $(grep -oE '^[A-Z_]*(KEY|SECRET)[A-Z_]*=' "$ENV_FILE" | tr -d '='); do
      val=$(_existing "$key" || true)
      (( ${#val} >= 6 )) || continue
      SECRET_VALUE="$val" perl -i -pe 's/\Q$ENV{SECRET_VALUE}\E/[redacted]/g' "$f"
    done
  fi
  chmod 600 "$f"
}

# ── steps ─────────────────────────────────────────────────────────────────

s_cloudflare() {
  stage "Cloudflare account"
  why "The reminder runs as a small program (a \"Worker\") on Cloudflare, in your" \
      "own account, so you own it and everything it stores. It needs the Workers" \
      "Paid plan (about US\$5 a month): one escalation can message every admin at" \
      "once, which is more than the free plan allows."
  todo "Sign in on the page that opens, and make sure the account is on Workers Paid (Workers & Pages > Plans)." \
       "Sign this computer in to that account when the next browser tab opens." \
       "Check that the account shown here is the right one."
  example "Plans page: \"Workers Paid · \$5/month\" is the current plan." \
          "Shown here afterwards: \"Example Pty Ltd  3f2a91c0…\""
  visit "https://dash.cloudflare.com/?to=/:account/workers/plans"
  confirm "Is your Cloudflare account on the Workers Paid plan?" || {
    fail "Upgrade to Workers Paid on the page above, then run this again."
    exit 1
  }
  printf '\n'
  say "Signing this computer in to Cloudflare (a browser tab may open)..."
  # `whoami` can exit 0 while signed out, so read what it says.
  if ! wr_quiet whoami || grep -qi "not authenticated" <<<"$WR_OUT"; then wr login; fi
  if ! wr_quiet whoami || grep -qi "not authenticated" <<<"$WR_OUT"; then
    fail "Couldn't read the signed-in Cloudflare account."
    exit 1
  fi
  # The account table only: the token's scopes, and wrangler's warning about
  # missing ones, are lines like "- account (read)" (#41).
  printf '%s\n' "$WR_OUT" | grep -E '[│┌├└]' | sed 's/^/  /' | head -12 || true
  if grep -qi "missing some expected oauth scopes" <<<"$WR_OUT"; then
    note "This computer's Cloudflare sign-in is missing some permissions: npx wrangler login refreshes them."
  fi
  printf '\n'
  confirm "Is that the account the reminder should run on?" || {
    fail "Run 'npx wrangler logout', then run this again and sign in to the right account."
    exit 1
  }
  next_up "the Connecteam key it uses."
}

s_key() {
  stage "Connecteam: API key"
  why "The reminder uses this key to see clock-outs and form submissions, and to" \
      "send its messages. It's stored only on your Cloudflare account. It also" \
      "tells us your daily API allowance: this needs Connecteam's Expert plan" \
      "(10,000 calls a day) or above, or it would run out of calls by lunchtime."
  todo "On the page that opens (Connecteam: Settings > API keys), create a new key." \
       "Paste it here. It won't show as you type."
  example "Name the key \"Clock-out Form Reminder\" so you can tell it apart later."
  visit "https://app.connecteam.com/#/settings/integrations/api"
  local verdict kind
  while :; do
    ask_secret CT_API_KEY "Paste the Connecteam API key:" || { fail "No key given."; exit 1; }
    say "Checking the key..."
    verdict=$(CT_API_KEY="$CT_API_KEY" npm run --silent check-api-key 2>/dev/null || true)
    kind=$(printf '%s' "$verdict" | json_get kind)
    case "$kind" in
      ok)
        save CT_API_KEY "$CT_API_KEY" "the API key"
        ok "Key works. Daily API allowance: $(printf '%s' "$verdict" | json_get dayLimit) calls a day."
        break ;;
      below_expert)
        fail "This account's daily API allowance is $(printf '%s' "$verdict" | json_get dayLimit) calls."
        say "The reminder needs Connecteam's Expert plan or above (10,000 calls a day)."
        say "On a smaller plan it would run out of calls by lunchtime, and every"
        say "other integration on the account would stop with it. Upgrade the plan"
        say "in Connecteam (Settings > Billing), then run this again."
        exit 1 ;;
      rejected)
        fail "Connecteam didn't accept that key."
        confirm "Paste it again? (make sure you copied the whole key)" || exit 1 ;;
      *)
        fail "Couldn't check the key: $(printf '%s' "$verdict" | json_get detail)"
        confirm "Try again?" || exit 1 ;;
    esac
  done
  next_up "your time zone."
}

# The suggested defaults (#19): 30-minute Grace Period, 4-hour escalation
# delay, Quiet Hours 9 pm to 7 am.
DEFAULT_GRACE=30
DEFAULT_DELAY=240
DEFAULT_QUIET_FROM="21:00"
DEFAULT_QUIET_UNTIL="07:00"
DEFAULT_WHERE="the Forms tab in the Connecteam app"

s_timezone() {
  stage "Time zone"
  why "Quiet hours (two steps from now) follow this time zone's clock, daylight" \
      "saving included. Shift times in messages always show the time where the" \
      "shift was recorded, so staff in another zone still see their own times."
  todo "Check the time zone below, read from your Connecteam time clock." \
       "Press Enter to keep it, or type another."
  example "Australia/Sydney, Australia/Perth, Pacific/Auckland, Europe/London"
  need_key
  local rc=0 suggested="" zone name current input
  helper time-zones || rc=$?
  if (( rc == 0 )); then
    suggested=$(printf '%s\n' "$HELPER_OUT" | head -n1 | cut -f1)
    while IFS=$'\t' read -r zone name; do ok "Time clock \"$name\" is set to $zone."; done <<<"$HELPER_OUT"
    if (( $(printf '%s\n' "$HELPER_OUT" | cut -f1 | sort -u | wc -l) > 1 )); then
      warn_long "Your time clocks use different time zones. Pick the one most of your admins work in: quiet hours follow it."
    fi
  else
    fail "$HELPER_OUT"
    (( rc == 3 )) && exit 1
    note "Type the time zone instead."
  fi
  current=$(_existing TIME_ZONE || true)
  if [[ -n "$current" && -n "$suggested" && "$current" != "$suggested" ]]; then
    note "Saved now: $current. Enter keeps it."
  fi
  while :; do
    ask_default input "Time zone:" "${current:-$suggested}" || { fail "No time zone given."; exit 1; }
    if helper zone "$input"; then break; fi
    fail "$HELPER_OUT"
  done
  save TIME_ZONE "$HELPER_OUT" "the time zone ($HELPER_OUT)"
  next_up "the form staff must submit."
}

# The form chosen in s_form, for the steps after it.
FORM_NAME=""
FORM_DATES=""

s_form() {
  stage "Compliance Form"
  why "This is the form every staff member must submit for every shift. The" \
      "reminder checks for a real submission of it, not a tick box."
  todo "Pick the form from your account's list below." \
       "A ⚠ means the form is set up in a way that can't work once per shift. You'll see why when you pick it."
  example "\"Daily Compliance Form\": staff fill it in at the end of every shift."
  need_key
  local rc=0 ids=() labels=() id label current def="" i n warnings w
  helper forms || rc=$?
  (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
  while IFS=$'\t' read -r id label; do ids+=("$id"); labels+=("$label"); done <<<"$HELPER_OUT"
  current=$(_existing COMPLIANCE_FORM_ID || true)
  for i in "${!ids[@]}"; do [[ "${ids[$i]}" == "$current" ]] && def=$((i + 1)); done
  while :; do
    printf '\n  Forms in your account:\n'
    choose n "Which form? (number)" "$def" 1 "${labels[@]}" || { fail "No form chosen."; exit 1; }
    id="${ids[$((n - 1))]}"
    rc=0; helper form "$id" || rc=$?
    (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
    FORM_NAME=$(grep '^name' <<<"$HELPER_OUT" | cut -f2-)
    warnings=$(grep '^warning' <<<"$HELPER_OUT" | cut -f2- || true)
    [[ -z "$warnings" ]] && break
    printf '\n'
    while IFS= read -r w; do warn_long "$w"; done <<<"$warnings"
    confirm "Use \"$FORM_NAME\" anyway?" && break
  done
  FORM_DATES=$(grep '^date' <<<"$HELPER_OUT" | cut -f2- || true)
  save COMPLIANCE_FORM_ID "$id" "the Compliance Form (\"$FORM_NAME\")"
  next_up "which question in it names the shift's date."
}

s_dateq() {
  stage "Shift date question (optional, recommended)"
  why "If someone misses the form on Monday and catches up on Wednesday, the" \
      "reminder needs to know which shift it's for. A date question in the form" \
      "(\"Which shift is this form for?\") answers that exactly. Without one, a" \
      "submission counts for the shift it was made during or just after, or else" \
      "the person's oldest missed form, which is usually right."
  todo "Pick the question that asks for the shift's date, or 0 for none."
  example "Jordan misses the form after Monday's shift and submits it on Wednesday," \
          "answering \"Which shift is this form for?\" with Monday. It counts for Monday."
  local qids=() titles=() qid title current def=1 i n
  if [[ -z "$FORM_DATES" ]]; then
    warn_long "\"$FORM_NAME\" has no date question. Consider adding one (\"Which shift is this form for?\"), then rerun: npm run setup -- --step form"
    save SHIFT_DATE_QUESTION_ID "" "the shift date question (none: submissions go by time)"
    next_up "where staff find the form."
    return
  fi
  while IFS=$'\t' read -r qid title; do qids+=("$qid"); titles+=("$title"); done <<<"$FORM_DATES"
  current=$(_existing SHIFT_DATE_QUESTION_ID || true)
  for i in "${!qids[@]}"; do [[ "${qids[$i]}" == "$current" ]] && def=$((i + 1)); done
  printf '\n  Date questions in "%s":\n' "$FORM_NAME"
  choose n "Which one asks for the shift's date? (number, or 0 for none)" "$def" 0 "${titles[@]}" \
    || { fail "No answer given."; exit 1; }
  if (( n == 0 )); then
    save SHIFT_DATE_QUESTION_ID "" "the shift date question (none: submissions go by time)"
  else
    save SHIFT_DATE_QUESTION_ID "${qids[$((n - 1))]}" "the shift date question (\"${titles[$((n - 1))]}\")"
  fi
  next_up "where staff find the form."
}

s_where() {
  stage "Where staff find the form"
  why "Connecteam can't give us a link to the form, so messages say where to find" \
      "it, in your own words. Your phrase finishes the sentence" \
      "\"You'll find it in …\"."
  todo "Finish the sentence below, or press Enter to keep the suggestion."
  example "You'll find it in the Forms tab in the Connecteam app." \
          "You'll find it in the \"End of shift\" folder under Forms."
  local input
  while :; do
    ask_default input "You'll find it in" "$(saved_or WHERE_TO_FIND "$DEFAULT_WHERE")" || { fail "Nothing given."; exit 1; }
    if helper where "$input"; then break; fi
    fail "$HELPER_OUT"
  done
  note "Messages will say: \"Where: $HELPER_OUT\""
  save WHERE_TO_FIND "$HELPER_OUT" "where staff find the form"
  next_up "how long people get before a reminder."
}

s_grace() {
  stage "Grace period"
  why "After someone clocks out, the reminder waits this long before checking for" \
      "the form, so people who fill it in straight away never get a message."
  todo "Type the grace period in minutes, or press Enter to keep the suggestion."
  local def input
  def=$(saved_or GRACE_PERIOD_MINUTES "$DEFAULT_GRACE")
  example_from_helper grace-example "$def"
  while :; do
    ask_default input "Grace period in minutes?" "$def" || { fail "Nothing given."; exit 1; }
    if helper duration grace "$input"; then break; fi
    fail "$HELPER_OUT"
  done
  local minutes="$HELPER_OUT"
  helper duration-label "$minutes" || HELPER_OUT="$minutes minutes"
  save GRACE_PERIOD_MINUTES "$minutes" "the grace period ($HELPER_OUT)"
  next_up "how long before your admins are told."
}

s_delay() {
  stage "Escalation delay"
  why "If the form is still missing this long after the reminder, your admins and" \
      "the employee's direct manager are told. It gives the employee a fair chance" \
      "to fix it first."
  todo "Type the delay in hours (1.5 or 90m work too), or press Enter to keep the suggestion."
  local grace def shown input
  grace=$(saved_or GRACE_PERIOD_MINUTES "$DEFAULT_GRACE")
  def=$(saved_or ESCALATION_DELAY_MINUTES "$DEFAULT_DELAY")
  if (( def % 60 == 0 )); then shown=$((def / 60)); else shown="${def}m"; fi
  example_from_helper delay-timeline "$grace" "$def"
  while :; do
    ask_default input "Escalation delay in hours?" "$shown" || { fail "Nothing given."; exit 1; }
    if helper duration delay "$input"; then break; fi
    fail "$HELPER_OUT"
  done
  local minutes="$HELPER_OUT"
  if [[ "$minutes" != "$def" ]]; then
    printf '\n  With that delay:\n'
    example_from_helper delay-timeline "$grace" "$minutes"
  fi
  helper duration-label "$minutes" || HELPER_OUT="$minutes minutes"
  save ESCALATION_DELAY_MINUTES "$minutes" "the escalation delay ($HELPER_OUT)"
  next_up "quiet hours."
}

s_quiet() {
  stage "Quiet hours"
  why "Escalations go to every admin, so they shouldn't arrive in the middle of the" \
      "night. During quiet hours they wait, then go out as one summary per admin" \
      "when quiet hours end. Reminders to the employee are never held: they've just" \
      "finished work and can fix it now."
  todo "Choose whether to use quiet hours. A team that works around the clock may want them off." \
       "If you use them, type when they start and end, or press Enter to keep the suggestions."
  local grace delay on qfrom quntil input
  grace=$(saved_or GRACE_PERIOD_MINUTES "$DEFAULT_GRACE")
  delay=$(saved_or ESCALATION_DELAY_MINUTES "$DEFAULT_DELAY")
  on=$(saved_or QUIET_HOURS_ENABLED true)
  qfrom=$(saved_or QUIET_HOURS_FROM "$DEFAULT_QUIET_FROM")
  quntil=$(saved_or QUIET_HOURS_UNTIL "$DEFAULT_QUIET_UNTIL")
  example_from_helper quiet-example "$grace" "$delay" "$qfrom" "$quntil"
  ask_yn input "Use quiet hours?" "$([[ "$on" == false ]] && echo n || echo y)" || { fail "No answer given."; exit 1; }
  if [[ "$input" == n ]]; then
    save QUIET_HOURS_ENABLED false "quiet hours (off)"
    warn "Escalations will go out at any hour, day or night."
    next_up "who receives escalations."
    return
  fi
  while :; do
    helper clock-label "$qfrom" || HELPER_OUT="$qfrom"
    while :; do
      ask_default input "Quiet from?" "$HELPER_OUT" || { fail "No answer given."; exit 1; }
      if helper clock "$input"; then qfrom="$HELPER_OUT"; break; fi
      fail "$HELPER_OUT"
    done
    helper clock-label "$quntil" || HELPER_OUT="$quntil"
    while :; do
      ask_default input "Quiet until?" "$HELPER_OUT" || { fail "No answer given."; exit 1; }
      if helper clock "$input"; then quntil="$HELPER_OUT"; break; fi
      fail "$HELPER_OUT"
    done
    [[ "$qfrom" != "$quntil" ]] && break
    fail "Quiet hours can't start and end at the same time. To have none, rerun this step and answer n."
  done
  if [[ "$on" == false || "$qfrom" != "$(saved_or QUIET_HOURS_FROM "$DEFAULT_QUIET_FROM")" || "$quntil" != "$(saved_or QUIET_HOURS_UNTIL "$DEFAULT_QUIET_UNTIL")" ]]; then
    printf '\n  With those times:\n'
    example_from_helper quiet-example "$grace" "$delay" "$qfrom" "$quntil"
  fi
  save QUIET_HOURS_ENABLED true "quiet hours (on)"
  save QUIET_HOURS_FROM "$qfrom" "when quiet hours start"
  save QUIET_HOURS_UNTIL "$quntil" "when quiet hours end"
  next_up "who receives escalations."
}

# Admins (user id <tab> label) and the direct-manager line, from `helper people`.
read_people() {
  local rc=0
  helper people || rc=$?
  (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
  ADMIN_IDS=(); ADMIN_LABELS=()
  local id label
  while IFS=$'\t' read -r id label; do ADMIN_IDS+=("$id"); ADMIN_LABELS+=("$label"); done < <(grep '^admin' <<<"$HELPER_OUT" | cut -f2-)
  DIRECT_LINE=$(grep '^direct' <<<"$HELPER_OUT" | cut -f2- || true)
}

# ticked_admins: the listed Admins not in the saved EXCLUDED_ADMIN_IDS, comma-separated.
ticked_admins() {
  local excl=",$(saved_or EXCLUDED_ADMIN_IDS "" | tr -d ' ')," out="" id
  for id in "${ADMIN_IDS[@]}"; do [[ "$excl" == *",$id,"* ]] || out+="${out:+,}$id"; done
  printf '%s' "$out"
}

s_recipients() {
  stage "Who receives escalations"
  why "Every admin in your Connecteam account receives escalations, plus the" \
      "employee's direct manager. Untick anyone who shouldn't be on every one." \
      "New admins are included automatically. An unticked admin still hears about" \
      "their own direct reports."
  todo "Check the list: everyone ticked (✔) gets escalations." \
       "Type a number to untick someone, or to tick them again. Press Enter when the list is right."
  example "The owner doesn't work with shift staff: type their number to untick them, then press Enter."
  need_key
  read_people
  ok "$DIRECT_LINE"
  # Unticked user ids, space-padded so " id " finds one. Saved ids no longer
  # Admins drop out here.
  local excl=" " saved_ids e i n kept
  saved_ids=$(saved_or EXCLUDED_ADMIN_IDS "")
  for e in ${saved_ids//,/ }; do
    for i in "${!ADMIN_IDS[@]}"; do [[ "${ADMIN_IDS[$i]}" == "$e" ]] && excl+="$e "; done
  done
  while :; do
    printf '\n  Admins (✔ = receives escalations):\n'
    for i in "${!ADMIN_IDS[@]}"; do
      if [[ "$excl" == *" ${ADMIN_IDS[$i]} "* ]]; then e=" "; else e="✔"; fi
      printf '    %s%3d)%s [%s] %s\n' "$BLUE" "$((i + 1))" "$RESET" "$e" "${ADMIN_LABELS[$i]}"
    done
    ask_default n "Number to untick or tick, or Enter when done:" "" || n=""
    [[ -z "$n" ]] && break
    if ! [[ "$n" =~ ^[0-9]+$ ]] || (( 10#$n < 1 || 10#$n > ${#ADMIN_IDS[@]} )); then
      fail "Type a number from the list, or press Enter when done."
      continue
    fi
    e="${ADMIN_IDS[$((10#$n - 1))]}"
    if [[ "$excl" == *" $e "* ]]; then excl="${excl/ $e / }"; else excl+="$e "; fi
    kept=0
    for i in "${!ADMIN_IDS[@]}"; do [[ "$excl" == *" ${ADMIN_IDS[$i]} "* ]] || kept=$((kept + 1)); done
    if (( kept == 0 )); then
      warn "At least one admin must stay ticked, or escalations would reach nobody."
      excl="${excl/ $e / }"
    fi
  done
  local list="" ticked=0
  for i in "${!ADMIN_IDS[@]}"; do
    if [[ "$excl" == *" ${ADMIN_IDS[$i]} "* ]]; then list+="${list:+,}${ADMIN_IDS[$i]}"; else ticked=$((ticked + 1)); fi
  done
  save EXCLUDED_ADMIN_IDS "$list" "the escalation recipients ($ticked of ${#ADMIN_IDS[@]} admins)"
  next_up "the reminder task."
}

s_task() {
  stage "Reminder task (on by default)"
  why "With the chat reminder, the employee also gets a task in their Connecteam" \
      "task list, so it stays visible after the message scrolls away. It ticks" \
      "itself off once the form arrives. Ticking it by hand doesn't count, and the" \
      "employee is told so."
  todo "Choose whether to create reminder tasks." \
       "If yes, pick the task board they go on."
  example "On the \"Compliance follow-ups\" board, Jordan sees a task named after the" \
          "form and the shift's day, until the form arrives."
  local on rc ids=() names=() id name current def="" i n
  ask_yn on "Create reminder tasks?" "$([[ "$(saved_or REMINDER_TASK_ENABLED true)" == false ]] && echo n || echo y)" \
    || { fail "No answer given."; exit 1; }
  if [[ "$on" == n ]]; then
    save REMINDER_TASK_ENABLED false "the reminder task (off)"
    next_up "the sender name staff will see."
    return
  fi
  need_key
  while :; do
    rc=0; helper boards || rc=$?
    (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
    [[ -n "$HELPER_OUT" ]] && break
    warn_long "There's no task board in use. Add one in Connecteam (Tasks), then press Enter here to look again."
    read -r _ || { fail "No task board to use."; exit 1; }
  done
  while IFS=$'\t' read -r id name; do ids+=("$id"); names+=("$name"); done <<<"$HELPER_OUT"
  current=$(_existing TASK_BOARD_ID || true)
  for i in "${!ids[@]}"; do [[ "${ids[$i]}" == "$current" ]] && def=$((i + 1)); done
  (( ${#ids[@]} == 1 )) && def=1
  printf '\n  Task boards:\n'
  choose n "Which board should the tasks go on? (number)" "$def" 1 "${names[@]}" || { fail "No board chosen."; exit 1; }
  save REMINDER_TASK_ENABLED true "the reminder task (on)"
  save TASK_BOARD_ID "${ids[$((n - 1))]}" "the task board (\"${names[$((n - 1))]}\")"
  next_up "the sender name staff will see."
}

s_sender() {
  stage "Sender name"
  why "Every message comes from this sender (a \"custom publisher\" in Connecteam)." \
      "Its name is the first thing staff see, so it should say the message is" \
      "automated, not from a person."
  todo "In Connecteam, open Settings > Feed settings > Custom publishers." \
       "Create one with a name like the example below, and save it." \
       "Come back here and type its publisher ID, or its number in the list below."
  example "Compliance Reminders (Automated)"
  need_key
  local rc ids=() names=() id name input i pick current
  current=$(_existing CT_PUBLISHER_ID || true)
  while :; do
    rc=0; helper publishers || rc=$?
    (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
    ids=(); names=()
    if [[ -n "$HELPER_OUT" ]]; then
      while IFS=$'\t' read -r id name; do ids+=("$id"); names+=("$name"); done <<<"$HELPER_OUT"
      printf '\n  Custom publishers in your account:\n'
      for i in "${!ids[@]}"; do printf '    %s%3d)%s %s %s(ID %s)%s\n' "$BLUE" "$((i + 1))" "$RESET" "${names[$i]}" "$DIM" "${ids[$i]}" "$RESET"; done
    else
      note "No custom publishers yet."
    fi
    ask_default input "Publisher ID (or its number in the list):" "$current" || { fail "No publisher given."; exit 1; }
    pick=""
    for i in "${!ids[@]}"; do [[ "${ids[$i]}" == "$input" ]] && pick=$i; done
    if [[ -z "$pick" && "$input" =~ ^[0-9]+$ ]] && (( 10#$input >= 1 && 10#$input <= ${#ids[@]} )); then pick=$((10#$input - 1)); fi
    [[ -n "$pick" ]] && break
    fail "That isn't one of your custom publishers. Created it just now? It's listed again below."
  done
  if ! helper automated "${names[$pick]}"; then
    warn_long "\"${names[$pick]}\" doesn't say it's automated, so staff may think a person wrote to them. Consider renaming it in Connecteam, then rerun: npm run setup -- --step sender"
  fi
  save CT_PUBLISHER_ID "${ids[$pick]}" "the sender (\"${names[$pick]}\")"
  write_env CT_PUBLISHER_NAME "${names[$pick]}" >/dev/null
  next_up "where problems are reported."
}

s_alerts() {
  stage "Alerts channel"
  why "If the reminder itself has a problem (Connecteam is down, the key stops" \
      "working, the form is deleted), it posts here, once per problem, with what" \
      "to do. This is about the system, never about staff."
  todo "Type part of the chat's name to pick it, or 0 to create a new channel for problems." \
       "A new channel's members are the admins ticked in the escalations step."
  example "In \"Form Reminder Alerts\": \"ALERT · FORM NOT FOUND … Action: rerun setup" \
          "step \"Compliance Form\".\""
  need_key
  local rc ids=() labels=() id label current def="" i n title members count channels=0
  rc=0; helper channels || rc=$?
  (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
  [[ -z "$HELPER_OUT" ]] || while IFS=$'\t' read -r id label; do ids+=("$id"); labels+=("$label"); done <<<"$HELPER_OUT"
  current=$(_existing ALERTS_CHANNEL_ID || true)
  for ((i = 0; i < ${#ids[@]}; i++)); do
    [[ "${ids[$i]}" == "$current" ]] && def="${labels[$i]}"
    [[ "${labels[$i]}" == *" (channel)" || "${labels[$i]}" == *" (channel, id "* ]] && channels=$((channels + 1))
  done
  while :; do
    # The helper lists channels first. An account can have dozens of team chats (#41).
    if (( ${#labels[@]} == 0 )); then
      printf '\n  No chats in your account yet.\n'
    elif (( ${#labels[@]} <= 20 )); then
      printf '\n  Chats in your account:\n'
      for ((i = 0; i < ${#labels[@]}; i++)); do step "${labels[$i]}"; done
    else
      printf '\n  Channels in your account:\n'
      for ((i = 0; i < channels && i < 20; i++)); do step "${labels[$i]}"; done
      (( channels > 0 )) || note "  (none yet)"
      note "Plus $(( ${#labels[@]} - (channels < 20 ? channels : 20) )) more chats: type part of a name to find one."
    fi
    find_by_name n "Which chat? (part of its name, or 0 to create a new channel)" "$def" 0 chat chats ${labels[@]+"${labels[@]}"} \
      || { fail "No chat chosen."; exit 1; }
    if (( n >= 0 )); then
      save ALERTS_CHANNEL_ID "${ids[$n]}" "the alerts channel (${labels[$n]})"
      break
    fi
    ask_default title "Name of the new channel:" "Form Reminder Alerts" || { fail "No name given."; exit 1; }
    read_people
    members=$(ticked_admins)
    [[ -n "$members" ]] || members=$(IFS=,; printf '%s' "${ADMIN_IDS[*]}")
    count=$(tr ',' '\n' <<<"$members" | wc -l | tr -d ' ')
    confirm "Create \"$title\" with $count admin(s) as members? They'll see it in their Connecteam chat." || continue
    if helper create-channel "$title" "$members"; then
      save ALERTS_CHANNEL_ID "$HELPER_OUT" "the alerts channel (\"$title\", new)"
      break
    fi
    fail "$HELPER_OUT"
  done
  if [[ -n "${WITH_SUPPORT:-}" ]]; then next_up "the support link."; else next_up "a tip about Connecteam's own clock-out question."; fi
}

# no_relay: save "no support link".
no_relay() {
  write_env INTEGRATOR_RELAY_URL "" >/dev/null
  write_env INTEGRATOR_CLIENT_SLUG "" >/dev/null
  write_env INTEGRATOR_RELAY_SECRET "" >/dev/null
  ok "Saved: no support link."
  next_up "a tip about Connecteam's own clock-out question."
}

s_relay() {
  stage "Support link (optional)"
  why "If your integrator supports this setup for you, problems are also sent to" \
      "them directly, even when Connecteam itself can't deliver them, plus a daily" \
      "\"still running\" check. Staff names are never sent, only counts."
  todo "Answer y only if your integrator gave you a support link." \
       "Then paste the link, the short name they gave you, and the secret." \
       "Answered y by mistake? Press Enter at the link with nothing typed."
  example "Link: https://clock-out-relay.example.workers.dev" \
          "Name: acme-cleaning (it appears in your integrator's issue titles, which are public)"
  local on input url slug
  ask_yn on "Send problems to your integrator as well?" "$([[ -n "$(saved_or INTEGRATOR_RELAY_URL "")" ]] && echo y || echo n)" \
    || { fail "No answer given."; exit 1; }
  if [[ "$on" == n ]]; then no_relay; return; fi
  while :; do
    ask_default input "Support link:" "$(saved_or INTEGRATOR_RELAY_URL "")" || { fail "No link given."; exit 1; }
    [[ -n "$input" ]] || { no_relay; return; }
    if helper relay-url "$input"; then url="$HELPER_OUT"; break; fi
    fail "$HELPER_OUT"
  done
  while :; do
    ask_default input "Your name for them:" "$(saved_or INTEGRATOR_CLIENT_SLUG "")" || { fail "No name given."; exit 1; }
    if helper slug "$input"; then slug="$HELPER_OUT"; break; fi
    fail "$HELPER_OUT"
  done
  while :; do
    ask_secret INTEGRATOR_RELAY_SECRET "Paste the secret (it won't show):" || { fail "No secret given."; exit 1; }
    [[ -n "$INTEGRATOR_RELAY_SECRET" ]] && break
    fail "The secret can't be blank. Your integrator gives you it with the link."
  done
  write_env INTEGRATOR_RELAY_URL "$url" >/dev/null
  write_env INTEGRATOR_CLIENT_SLUG "$slug" >/dev/null
  save INTEGRATOR_RELAY_SECRET "$INTEGRATOR_RELAY_SECRET" "the support link ($slug)"
  next_up "a tip about Connecteam's own clock-out question."
}

s_tip() {
  stage "Tip: a clock-out question in Connecteam (optional)"
  why "Connecteam can ask staff a required question before they clock out, such as" \
      "\"Have you submitted the compliance form?\". It's only their word, so this" \
      "reminder still checks for the real form, but it's a useful nudge at the" \
      "right moment."
  todo "If you'd like one: in Connecteam, open Time Clock > Settings > Shift Entries, and add a required question under \"During shift or before clocking out\"."
  example "\"Have you submitted the ${FORM_NAME:-compliance form}?\" with the answers Yes and No."
  note "Nothing to enter here."
  pause "Press Enter to continue"
}

# ── turning it on (#40) ───────────────────────────────────────────────────

DB_NAME="clock-out-form-reminder"
# The config every remote command uses, built from wrangler.jsonc + $ENV_FILE.
DEPLOY_CONFIG="${WIZARD_DEPLOY_CONFIG:-wrangler.deploy.json}"

# deploy_config: build and check that config (scripts/deploy-config.ts
# --check-live), its output left in $DC_OUT and kept in $WIZARD_DETAILS.
deploy_config() {
  local rc=0
  DC_OUT=$(DEV_VARS_FILE="$ENV_FILE" DEPLOY_CONFIG_FILE="$DEPLOY_CONFIG" npm run --silent deploy:config -- --check-live < /dev/null 2>&1) || rc=$?
  { printf '\n$ npm run deploy:config -- --check-live   (exit %s, %s)\n' "$rc" "$(date +%H:%M:%S)"; printf '%s\n' "$DC_OUT"; } >> "$WIZARD_DETAILS"
  return "$rc"
}

# show_wr_tail: the end of the last wrangler call's output, for a failure.
show_wr_tail() {
  printf '%s\n' "$WR_OUT" | perl -pe 's/\e\[[0-9;]*[A-Za-z]//g' | tail -15 | sed 's/^/    /'
  note "Full output: ${WIZARD_DETAILS#"$PWD"/}"
}

# put_secret NAME VALUE "label": store a secret on the Worker, the value piped, never an argument.
put_secret() {
  local out rc=0
  out=$(printf '%s' "$2" | wrangler_bin secret put "$1" --config "$DEPLOY_CONFIG" 2>&1) || rc=$?
  { printf '\n$ wrangler secret put %s --config %s   (exit %s, %s)\n' "$1" "$DEPLOY_CONFIG" "$rc" "$(date +%H:%M:%S)"; printf '%s\n' "$out"; } >> "$WIZARD_DETAILS"
  if (( rc == 0 )); then ok "Stored $3 on Cloudflare."; return 0; fi
  fail "Couldn't store $3 on Cloudflare. Without it the reminder can't run."
  note "Store it by hand: npx wrangler secret put $1 --config wrangler.deploy.json"
  note "Full output: ${WIZARD_DETAILS#"$PWD"/}"
  exit 1
}

# check_config: build and check the deploy config, or stop; settings it
# would change on the live Worker are shown.
check_config() {
  deploy_config || { fail "The deploy settings aren't ready:"; printf '%s\n' "$DC_OUT" | sed 's/^/    /'; return 1; }
  if grep -q '^!' <<<"$DC_OUT"; then
    printf '%s\n' "$DC_OUT" | sed -n '/^!/,$p' | sed 's/^/  /'
  fi
}

# migrate: bring the database up to date (safe to repeat).
migrate() {
  wr_quiet d1 migrations apply "$DB_NAME" --remote --config "$DEPLOY_CONFIG" \
    || { fail "Couldn't set up the database:"; show_wr_tail; exit 1; }
  ok "Database up to date."
}

# deploy_worker: the checked deploy, the Worker's address left in $WORKER_URL.
WORKER_URL=""
deploy_worker() {
  say "Deploying (about a minute)..."
  wr_quiet deploy --config "$DEPLOY_CONFIG" || { fail "The deploy failed:"; show_wr_tail; exit 1; }
  WORKER_URL=$(printf '%s' "$WR_OUT" | grep -oE 'https://[a-zA-Z0-9.-]+\.workers\.dev' | head -1 || true)
}

# need_worker_url: stop when the deploy didn't say where the Worker is.
need_worker_url() {
  [[ -z "$WORKER_URL" ]] || return 0
  fail "Deployed, but couldn't read the reminder's address from Cloudflare."
  note "Find it in Cloudflare (Workers & Pages > $DB_NAME), then subscribe the webhooks"
  note "by hand: docs/RUNBOOK.md, \"Subscribing the webhooks\"."
  exit 1
}

# subscribe_webhooks: make Connecteam hold exactly this Deployment's subscriptions.
subscribe_webhooks() {
  local rc=0 what line
  helper webhooks "$WORKER_URL/webhook" || rc=$?
  while IFS=$'\t' read -r what line; do
    case "$what" in
      updated) ok "Connecteam webhook updated: $line" ;;
      created) ok "Connecteam webhook added: $line" ;;
      removed) ok "Connecteam webhook removed: $line" ;;
      *) [[ -z "$what" ]] || fail "$what${line:+ $line}" ;;
    esac
  done <<<"$HELPER_OUT"
  if (( rc != 0 )); then
    note "Rerun npm run setup -- --step webhook to try again: it updates what's there rather than adding more."
    exit 1
  fi
}

s_summary() {
  stage "Check your settings"
  why "Nothing is live yet. Here is every setting in one place, so you can check" \
      "them before the reminder starts watching your time clock."
  todo "Read the list below." \
       "Answer y to turn the reminder on, or n to stop and change something first."
  example "Sender ............... Compliance Reminders (Automated)"
  need_key
  local rc=0 l
  helper summary || rc=$?
  if (( rc == 1 )); then
    fail "Some settings are missing or wrong:"
    while IFS= read -r l; do note "  $l"; done <<<"$HELPER_OUT"
    exit 1
  fi
  (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
  printf '\n'
  while IFS= read -r l; do say "$l"; done <<<"$HELPER_OUT"
  printf '\n'
  confirm "Is this right? Answering y turns the reminder on." || {
    warn "Stopped. Nothing went live."
    note "Change a setting with: npm run setup -- --step NAME (see --help), then run npm run setup again."
    exit 1
  }
  next_up "turn it on."
}

s_turn_on() {
  stage "Turn it on"
  why "This installs the reminder on your Cloudflare account, then asks Connecteam" \
      "to tell it about clock-outs, form submissions and ticked tasks."
  todo "Nothing to type: watch each line below. It takes a minute or two."
  example "✓ Database created." \
          "✓ Deployed: https://clock-out-form-reminder.example.workers.dev"
  need_key
  printf '\n'

  # The webhook secret Connecteam sends with every delivery. Kept on a rerun:
  # a new one would turn away deliveries until the webhooks are updated too.
  local secret
  secret=$(_existing CT_WEBHOOK_SECRET || true)
  if [[ -n "$secret" ]]; then
    ok "Kept the webhook secret already saved."
  else
    secret=$(node -e 'console.log(require("crypto").randomBytes(32).toString("hex"))')
    write_env CT_WEBHOOK_SECRET "$secret" >/dev/null
    ok "Made a webhook secret."
  fi

  # The database: the one already saved, else one by this name, else a new one.
  local db saved_db
  saved_db=$(_existing D1_DATABASE_ID || true)
  wr_quiet d1 list --json || { fail "Couldn't list this Cloudflare account's databases:"; show_wr_tail; exit 1; }
  db=$(printf '%s' "$WR_OUT" | node -e '
    let s = ""; process.stdin.on("data", d => s += d).on("end", () => {
      try {
        const list = JSON.parse(s.slice(s.indexOf("[")));
        const m = list.find(d => d.uuid === process.argv[1]) || list.find(d => d.name === process.argv[2]);
        console.log(m ? m.uuid : "");
      } catch { console.log(""); }
    })' "$saved_db" "$DB_NAME")
  if [[ -n "$db" ]]; then
    ok "Reusing the database already on this account."
  else
    wr_quiet d1 create "$DB_NAME" || { fail "Couldn't create the database:"; show_wr_tail; exit 1; }
    db=$(printf '%s' "$WR_OUT" | grep -oiE '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' | head -1 || true)
    [[ -n "$db" ]] || { fail "Created the database but couldn't read its id:"; show_wr_tail; exit 1; }
    ok "Database created."
  fi
  write_env D1_DATABASE_ID "$db" >/dev/null

  # Every remote command from here goes through the checked config.
  check_config || exit 1
  migrate
  deploy_worker
  # Secrets after the deploy: `secret put` on a Worker that doesn't exist yet
  # stops to ask whether to create one.
  put_secret CT_API_KEY "$CT_API_KEY" "the API key"
  put_secret CT_WEBHOOK_SECRET "$secret" "the webhook secret"
  local relay_secret
  relay_secret=$(_existing INTEGRATOR_RELAY_SECRET || true)
  [[ -z "$relay_secret" ]] || put_secret INTEGRATOR_RELAY_SECRET "$relay_secret" "the support link's secret"
  need_worker_url
  ok "Deployed: $WORKER_URL"
  subscribe_webhooks
  ok "Installed. It checks every minute from now on."
  next_up "a test message."
}

s_webhook() {
  stage "Connecteam webhooks"
  why "Connecteam tells the reminder about clock-outs, form submissions and ticked" \
      "tasks through three webhook subscriptions. This puts back exactly those" \
      "three, for this reminder's address only. Other integrations' webhooks on" \
      "your account are never touched."
  todo "Check what will change in Connecteam, then answer y." \
       "If Connecteam no longer has any of this reminder's webhooks, it asks first, then redeploys the reminder as it is to read its address."
  example "Update: forms (id 5012)" \
          "Left alone: 2 other webhooks on your account"
  need_key
  [[ -n "$(_existing D1_DATABASE_ID || true)" ]] || { fail "The reminder isn't on yet. Turn it on first: npm run setup"; exit 1; }
  printf '\n'
  local rc=0 what line
  # Its address from its own webhooks, so nothing is deployed unasked (#41).
  helper worker-url || rc=$?
  if (( rc == 0 )); then
    WORKER_URL="$HELPER_OUT"
    ok "This reminder is at $WORKER_URL."
  else
    (( rc == 1 )) || { fail "$HELPER_OUT"; exit 1; }
    note "$HELPER_OUT Its address comes from a deploy instead."
    check_config || exit 1
    confirm "Deploy the reminder as it is now, to read its address?" || { note "Nothing changed."; return 0; }
    deploy_worker
    need_worker_url
    ok "Deployed: $WORKER_URL"
  fi
  rc=0
  helper webhooks "$WORKER_URL/webhook" --plan || rc=$?
  (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
  printf '\n  %sWhat this changes%s\n' "$BOLD" "$RESET"
  while IFS=$'\t' read -r what line; do
    case "$what" in
      update) step "Update: $line" ;;
      create) step "Add: $line" ;;
      remove) step "Remove: $line" ;;
      others) if [[ "$line" == 1 ]]; then step "Left alone: 1 other webhook on your account"; else step "Left alone: $line other webhooks on your account"; fi ;;
    esac
  done <<<"$HELPER_OUT"
  printf '\n'
  confirm "Make these changes in Connecteam?" || { note "Nothing changed in Connecteam."; return 0; }
  subscribe_webhooks
  ok "Done. Connecteam sends this reminder exactly what it needs."
}

s_test() {
  stage "Test message"
  why "To check it all works, this sends one real reminder, exactly as staff will" \
      "see it, about a sample shift today. Nobody else is told, and nothing is" \
      "recorded against anyone."
  todo "Pick who gets it: you, or someone with the Connecteam app to hand (on a call, the client)." \
       "Check it arrives on their phone."
  example "Type part of a name, like \"jor\" for Jordan Lee, then pick from the matches."
  need_key
  local rc=0 ids=() labels=() id label def="" owners=0 pick=""
  helper users || rc=$?
  (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
  while IFS=$'\t' read -r id label; do
    ids+=("$id"); labels+=("$label")
    if [[ "$label" == *" (owner)" ]]; then owners=$((owners + 1)); def="$label"; fi
  done <<<"$HELPER_OUT"
  (( owners == 1 )) || def=""
  find_by_name pick "Send the test to (part of a name):" "$def" "" one people ${labels[@]+"${labels[@]}"} \
    || { fail "No one picked."; exit 1; }
  confirm "Send the test reminder to ${labels[$pick]} now?" || { note "Not sent. Send one later with: npm run setup -- --step test"; return 0; }
  rc=0
  helper test-message "${ids[$pick]}" || rc=$?
  (( rc == 0 )) || { fail "$HELPER_OUT"; exit 1; }
  ok "Sent to ${labels[$pick]}:"
  local lines=() l
  while IFS= read -r l; do lines+=("$l"); done <<<"$HELPER_OUT"
  example "${lines[@]}"
  if confirm "Did it arrive?"; then
    ok "All set."
  else
    warn_long "Check that ${labels[$pick]} is signed in to the Connecteam app with notifications on, and look in their chats for the sender's name. If it still isn't there, send this session's log to your integrator."
  fi
}

s_done() {
  printf '\n'
  ok "The reminder is on."
  note "From now on, when someone clocks out without submitting the Compliance Form,"
  note "they're reminded once the grace period ends, and your admins hear about it if"
  note "it's still missing after the escalation delay."
  note "To change one thing later: npm run setup -- --step NAME (see --help)."
}

# apply_rerun BEFORE: after a --step rerun on a running Deployment (#41),
# say what the change affects, counted in D1, then on a yes run the checking
# deploy, store a secret that changed, and move the webhooks a form or board
# change moves. On a no, .dev.vars goes back to the copy BEFORE.
apply_rerun() {
  local before="$1" keys l d1
  helper changed "$before" || { fail "$HELPER_OUT"; exit 1; }
  keys=$'\n'"$HELPER_OUT"$'\n'
  printf '\n'
  if [[ -z "${HELPER_OUT//[[:space:]]/}" ]]; then RERUN_KEEP=1; ok "Nothing changed, so there's nothing to apply."; return 0; fi
  if [[ -z "$(_existing D1_DATABASE_ID || true)" ]]; then
    RERUN_KEEP=1
    note "Saved to $ENV_FILE. It goes live when you finish setup: npm run setup"
    return 0
  fi
  if ! check_config; then
    restore_env "$before"
    note "Fix that, then rerun this step."
    exit 1
  fi
  d1=$(mktemp)
  helper impact-sql || { fail "$HELPER_OUT"; exit 1; }
  if wr_quiet d1 execute "$DB_NAME" --remote --json --config "$DEPLOY_CONFIG" --command "$HELPER_OUT"; then
    printf '%s' "$WR_OUT" > "$d1"
  fi
  helper impact "$before" "$d1" || true
  rm -f "$d1"
  printf '\n  %sWhat this changes%s\n' "$BOLD" "$RESET"
  while IFS= read -r l; do [[ -z "$l" ]] || point "$l"; done <<<"$HELPER_OUT"
  printf '\n'
  if ! confirm "Apply it now?"; then
    restore_env "$before"
    return 0
  fi
  migrate
  deploy_worker
  # Live now: keep it, even if a step below fails.
  RERUN_KEEP=1
  [[ "$keys" != *$'\nCT_API_KEY\n'* ]] || put_secret CT_API_KEY "$(_existing CT_API_KEY)" "the API key"
  if [[ "$keys" == *$'\nINTEGRATOR_RELAY_SECRET\n'* && -n "$(_existing INTEGRATOR_RELAY_SECRET || true)" ]]; then
    put_secret INTEGRATOR_RELAY_SECRET "$(_existing INTEGRATOR_RELAY_SECRET)" "the support link's secret"
  fi
  if [[ "$keys" == *$'\nCOMPLIANCE_FORM_ID\n'* || "$keys" == *$'\nTASK_BOARD_ID\n'* ]]; then
    need_worker_url
    subscribe_webhooks
  fi
  ok "Applied. The reminder uses it from its next check, within a minute."
}

# restore_env BEFORE: put .dev.vars back as the copy BEFORE has it.
restore_env() {
  if [[ -f "$1" ]]; then cat "$1" > "$ENV_FILE"; else rm -f "$ENV_FILE"; fi
  RERUN_KEEP=1
  WRITTEN_ENV=()
  warn "Not applied. $ENV_FILE is back as it was."
}

# end_rerun: on any exit (Ctrl-C included), a change not yet live goes back,
# so nothing reaches the Worker without a yes; then the copy is removed.
RERUN_KEEP=""
end_rerun() {
  if [[ -z "$RERUN_KEEP" ]]; then
    # Said only when there's something to put back.
    if [[ -f "$RERUN_BEFORE" ]] && cmp -s "$RERUN_BEFORE" "$ENV_FILE"; then :
    elif [[ ! -f "$RERUN_BEFORE" && ! -f "$ENV_FILE" ]]; then :
    else printf '\n'; restore_env "$RERUN_BEFORE"; fi
  fi
  rm -f "$RERUN_BEFORE"
}

# Each step by --step name, and how many stages it shows.
run_step() {
  case "$1" in
    key) s_key ;;
    timezone) s_timezone ;;
    form) s_form; s_dateq; s_where ;;
    timings) s_grace; s_delay ;;
    quiet-hours) s_quiet ;;
    recipients) s_recipients ;;
    reminder-task) s_task ;;
    sender) s_sender ;;
    alerts) s_alerts ;;
    support) s_relay ;;
    webhook) s_webhook ;;
    test) s_test ;;
  esac
}
step_stages() {
  case "$1" in
    form) echo 3 ;;
    timings) echo 2 ;;
    *) echo 1 ;;
  esac
}

usage() {
  cat <<USAGE
Clock-out Form Reminder setup

  npm run setup                    full first-time setup
  npm run setup -- --support       the same, with the support link your integrator gave you
  npm run setup -- --step NAME     rerun one step, see what it affects, then apply it
  npm run setup -- --help          this message

Steps: ${STEPS[*]}
USAGE
}

run_wizard() {

ONLY=""
WITH_SUPPORT=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --step) ONLY="${2:-}"; [[ -n "$ONLY" ]] || { usage >&2; exit 2; }; shift ;;
    --support) WITH_SUPPORT=1 ;;
    -h|--help) usage; exit 0 ;;
    *) printf 'unknown option: %s\n\n' "$1" >&2; usage >&2; exit 2 ;;
  esac
  shift
done
if [[ -n "$ONLY" ]]; then
  [[ " ${STEPS[*]} " == *" $ONLY "* ]] || { printf 'unknown step: %s\n\n' "$ONLY" >&2; usage >&2; exit 2; }
fi

# ── prerequisites (before anything is asked, so a missing tool fails fast) ─
for _c in node npm npx git curl; do
  command -v "$_c" >/dev/null 2>&1 || { printf 'missing required tool: %s\n' "$_c" >&2; exit 1; }
done
grep -q '"name": "clock-out-form-reminder"' package.json 2>/dev/null \
  || { printf 'run this from the TC_TO_FORM_RMDR repo root\n' >&2; exit 1; }
[[ -d node_modules ]] || { printf 'installing dependencies...\n'; npm install; }

# The session log: record the run, then clean and redact it (see clean_log).
if [[ -z "${WIZARD_LOG:-}" && -t 0 && -t 1 ]] && command -v script >/dev/null 2>&1 && command -v perl >/dev/null 2>&1; then
  export WIZARD_LOG="$PWD/setup-wizard-$(date +%Y%m%d-%H%M%S).log"
  export WIZARD_DETAILS="${WIZARD_LOG%.log}-wrangler.log"
  # Ctrl-C stops the recorded wizard; this outer shell carries on to clean up.
  # A no-op handler, not `trap ''`: an ignored signal is inherited.
  trap ':' INT
  if script --version >/dev/null 2>&1; then
    script -q -e -c "$(printf '%q ' bash "$0" "$@")" "$WIZARD_LOG" && rc=0 || rc=$?   # Linux / WSL
  else
    script -q "$WIZARD_LOG" bash "$0" "$@" && rc=0 || rc=$?                            # macOS
  fi
  trap - INT
  clean_log "$WIZARD_LOG"
  clean_log "$WIZARD_DETAILS"
  printf '\n  %sA copy of this run is in %s (keys hidden). Send it to your integrator if anything looked wrong.%s\n\n' \
    "$DIM" "${WIZARD_LOG#"$PWD"/}" "$RESET"
  exit "$rc"
fi

if [[ -n "$ONLY" ]]; then
  TOTAL_STAGES=$(step_stages "$ONLY")
  # A copy of .dev.vars as it was (it holds keys: mktemp makes it 0600), to
  # compare with and to put back if the change isn't applied.
  RERUN_BEFORE=$(mktemp)
  if [[ -f "$ENV_FILE" ]]; then cat "$ENV_FILE" > "$RERUN_BEFORE"; else rm -f "$RERUN_BEFORE"; fi
  # test and webhook change no setting.
  case "$ONLY" in test | webhook) RERUN_KEEP=1 ;; esac
  trap end_rerun EXIT
  trap 'exit 130' INT
  run_step "$ONLY"
  [[ -n "$RERUN_KEEP" ]] || apply_rerun "$RERUN_BEFORE"
  finish
  return
fi

# The support link is asked only when an integrator gave one: with --support,
# or when one is saved, so a rerun keeps it (#41).
[[ -z "$(saved_or INTEGRATOR_RELAY_URL "")" ]] || WITH_SUPPORT=1
if [[ -n "$WITH_SUPPORT" ]]; then TOTAL_STAGES=18; else TOTAL_STAGES=17; fi
banner "Clock-out Form Reminder: setup"
s_cloudflare
s_key
s_timezone
s_form; s_dateq; s_where
s_grace; s_delay
s_quiet
s_recipients
s_task
s_sender
s_alerts
[[ -z "$WITH_SUPPORT" ]] || s_relay
s_tip
s_summary
s_turn_on
s_test
finish
s_done
}

run_wizard "$@"; exit
